#include "zs_sx1262.h"
#include <string.h>
const uint32_t zs_ru868_candidate_channels_hz[7]={864100000u,864300000u,864500000u,864700000u,864900000u,868900000u,869100000u};
bool zs_sx1262_frequency_allowed_ru868(uint32_t hz){for(size_t i=0;i<7u;i++)if(zs_ru868_candidate_channels_hz[i]==hz)return true;return false;}
static bool wait_busy(zs_sx1262_t*r){if(!r->io.gpio_read)return true;for(unsigned i=0;i<1000;i++){if(!r->io.gpio_read(r->io.ctx,r->busy_gpio))return true;if(r->io.delay_ms)r->io.delay_ms(r->io.ctx,1);}return false;}
static bool cmd(zs_sx1262_t*r,uint8_t op,const uint8_t*p,size_t n){if(!r||!r->io.spi_transfer||!wait_busy(r))return false;uint8_t tx[16]={0},rx[16]={0};if(n+1>sizeof(tx))return false;tx[0]=op;if(n)memcpy(tx+1,p,n);if(r->io.gpio_write)r->io.gpio_write(r->io.ctx,r->nss_gpio,false);int z=r->io.spi_transfer(r->io.ctx,r->spi_bus,tx,rx,n+1);if(r->io.gpio_write)r->io.gpio_write(r->io.ctx,r->nss_gpio,true);return z>=0&&wait_busy(r);}
void zs_sx1262_init(zs_sx1262_t*r,const zs_hal_port_t*io,unsigned spi,unsigned nss,unsigned busy,unsigned reset){if(!r)return;memset(r,0,sizeof(*r));if(io)r->io=*io;r->spi_bus=spi;r->nss_gpio=nss;r->busy_gpio=busy;r->reset_gpio=reset;r->sf=9;r->bw_code=4;r->cr_code=1;}
bool zs_sx1262_reset(zs_sx1262_t*r){if(!r)return false;if(r->io.gpio_write){r->io.gpio_write(r->io.ctx,r->reset_gpio,false);if(r->io.delay_ms)r->io.delay_ms(r->io.ctx,2);r->io.gpio_write(r->io.ctx,r->reset_gpio,true);if(r->io.delay_ms)r->io.delay_ms(r->io.ctx,10);}return wait_busy(r);}
bool zs_sx1262_set_standby(zs_sx1262_t*r){uint8_t x=0;return cmd(r,0x80,&x,1);}bool zs_sx1262_set_sleep(zs_sx1262_t*r){uint8_t x=0x04;return cmd(r,0x84,&x,1);}bool zs_sx1262_set_frequency(zs_sx1262_t*r,uint32_t hz){if(!zs_sx1262_frequency_allowed_ru868(hz))return false;uint32_t reg=(uint32_t)(((uint64_t)hz<<25)/32000000u);uint8_t x[4]={(uint8_t)(reg>>24),(uint8_t)(reg>>16),(uint8_t)(reg>>8),(uint8_t)reg};if(cmd(r,0x86,x,4)){r->frequency_hz=hz;return true;}return false;}
static uint8_t bw(uint32_t h){if(h<=7800)return 0;if(h<=10400)return 8;if(h<=15600)return 1;if(h<=20800)return 9;if(h<=31250)return 2;if(h<=41700)return 10;if(h<=62500)return 3;if(h<=125000)return 4;if(h<=250000)return 5;return 6;}
bool zs_sx1262_set_lora_modulation(zs_sx1262_t*r,uint8_t sf,uint32_t bandwidth,uint8_t crden){if(sf<5||sf>12)return false;uint8_t cr=(crden>=5&&crden<=8)?(uint8_t)(crden-4):1;uint8_t x[4]={sf,bw(bandwidth),cr,(sf>=11&&bandwidth==125000)?1:0};if(cmd(r,0x8B,x,4)){r->sf=sf;r->bw_code=x[1];r->cr_code=cr;return true;}return false;}
static uint32_t tick24(uint32_t us){uint64_t v=(uint64_t)us*64u/1000u;if(v>0xFFFFFFu)v=0xFFFFFFu;return (uint32_t)v;}
bool zs_sx1262_start_rx_duty_cycle(zs_sx1262_t*r,uint32_t rx_us,uint32_t sleep_us){uint32_t a=tick24(rx_us),b=tick24(sleep_us);uint8_t x[6]={(uint8_t)(a>>16),(uint8_t)(a>>8),(uint8_t)a,(uint8_t)(b>>16),(uint8_t)(b>>8),(uint8_t)b};return cmd(r,0x94,x,6);}
